// FRAnime.fr (franime.fr): French anime streaming (VOSTFR and VF) backed by api.franime.fr.
//
// Search and episode listings use the JSON API (`https://api.franime.fr/api/animes` and
// `https://api.franime.fr/api/anime-by-id/<id>`). Player resolution calls
// `https://api.franime.fr/api/anime/<id>/<season>/<ep>/<lang>/<lecteur>`, decodes the
// `/watch2/?b=...` Base64+Hex+XOR payload to obtain the embed URL, and extracts the direct
// HLS (.m3u8) or MP4 stream from Sendvid, Vidmoly, Uqload, or Smoothpre.

class Provider {
  constructor() {
    this.base = "https://franime.fr";
    this.api = "https://api.franime.fr/api";
    this.servers = ["Sendvid", "Vidmoly", "Uqload", "Smoothpre"];
    this._indexCache = null;
    this._indexAt = 0;
    this._indexPromise = null;
    this._animeCache = {};
    this._animePromises = {};
  }

  getSettings() {
    return {
      episodeServers: this.servers.slice(),
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    const queries = this._queries(opts);
    if (queries.length === 0) return [];
    const qWords = queries.map((q) => this._words(q)).filter((w) => w.length > 0);
    if (qWords.length === 0) return [];
    const dub = !!(opts && opts.dub);
    const langKey = dub ? "vf" : "vo";

    const index = await this._catalogueIndex();
    const scored = [];
    for (let i = 0; i < index.length; i++) {
      const entry = index[i];
      let best = 0;
      for (let q = 0; q < qWords.length; q++) {
        const qw = qWords[q];
        const qBonus = q < 3 ? 0.01 : 0;
        for (let p = 0; p < entry.primaryWords.length; p++) {
          const s = this._scoreWords(qw, entry.primaryWords[p]);
          if (s > 0) best = Math.max(best, s + 0.02 + qBonus);
        }
        for (let n = 0; n < entry.nameWords.length; n++) {
          const s = this._scoreWords(qw, entry.nameWords[n]);
          if (s > 0) best = Math.max(best, s + qBonus);
        }
      }
      if (best >= 0.45) scored.push({ entry: entry, score: best });
    }
    scored.sort(function (a, b) {
      return b.score - a.score;
    });

    const hits = scored.slice(0, 5);
    const self = this;
    const details = await Promise.all(
      hits.map(function (item) {
        return self._anime(item.entry.id).then(null, function () {
          return null;
        });
      })
    );

    const results = [];
    for (let h = 0; h < hits.length; h++) {
      const anime = details[h];
      if (!anime || !Array.isArray(anime.saisons)) continue;
      const baseNames = hits[h].entry.names.slice();
      const baseTitle = this._text(anime.title) || this._text(anime.titleO) || baseNames[0] || String(anime.id);
      const slug = this._slug(anime.titleO || anime.title || baseTitle);

      const want2014 = /2014|final\s+chapters/i.test(queries.join(" "));
      const groups = this._buildSeasonGroups(anime, baseTitle, langKey, want2014);
      for (let g = 0; g < groups.length; g++) {
        const grp = groups[g];
        const title = grp.title;
        const altTitles = [];
        const addAlt = function (t) {
          if (t && t !== title && altTitles.indexOf(t) < 0) altTitles.push(t);
        };
        for (let a = 0; a < grp.altTitles.length; a++) addAlt(grp.altTitles[a]);

        results.push({
          id: [String(anime.id), grp.spec, langKey].join("|"),
          title: title,
          url: this.base + "/anime/" + slug + "?s=" + (grp.firstSeasonIdx + 1) + "&lang=" + langKey,
          subOrDub: dub ? "dub" : "sub",
          altTitles: altTitles,
        });
      }
    }
    return results;
  }

  async findEpisodes(id) {
    const parts = String(id || "").split("|");
    const animeId = parseInt(parts[0], 10);
    const spec = String(parts[1] || "0");
    const langKey = parts[2] === "vf" ? "vf" : "vo";
    if (!(animeId > 0)) throw new Error("invalid series id '" + id + "'");

    const atParts = spec.split("@");
    const sIndices = atParts[0]
      .split(",")
      .map(function (x) {
        return parseInt(x, 10);
      })
      .filter(function (n) {
        return n >= 0;
      });
    const offset = atParts[1] ? parseInt(atParts[1], 10) || 0 : 0;
    if (sIndices.length === 0) throw new Error("invalid season spec in '" + id + "'");

    const anime = await this._anime(animeId);
    if (!anime || !Array.isArray(anime.saisons)) throw new Error("anime not found on franime.fr");

    const slug = this._slug(anime.titleO || anime.title || String(animeId));
    const byNumber = {};
    const orderNums = [];

    for (let i = 0; i < sIndices.length; i++) {
      const sIdx = sIndices[i];
      const saison = anime.saisons[sIdx];
      if (!saison || !Array.isArray(saison.episodes)) continue;
      const useTitleNum = sIndices.length > 1 && this._isContinuousSaga(saison);

      for (let epIdx = 0; epIdx < saison.episodes.length; epIdx++) {
        const ep = saison.episodes[epIdx];
        if (this._lecteursOf(ep, langKey).length === 0) continue;
        const epTitle = this._text(ep && ep.title);
        const parsedNum = useTitleNum ? this._epNumberFromTitle(epTitle) : null;
        const rawNumber = parsedNum !== null ? parsedNum : epIdx + 1;
        const number = rawNumber - offset;
        if (!(number > 0)) continue;

        const key = String(number);
        if (!byNumber[key]) {
          byNumber[key] = {
            number: number,
            pairs: [],
            title: epTitle || "Épisode " + number,
            firstSIdx: sIdx,
            firstEpIdx: epIdx,
          };
          orderNums.push(number);
        }
        const pair = sIdx + ":" + epIdx;
        if (byNumber[key].pairs.indexOf(pair) < 0) {
          byNumber[key].pairs.push(pair);
        }
      }
    }

    orderNums.sort(function (a, b) {
      return a - b;
    });
    const episodes = [];
    for (let i = 0; i < orderNums.length; i++) {
      const item = byNumber[String(orderNums[i])];
      episodes.push({
        id: [String(animeId), item.pairs.join(","), langKey].join("|"),
        number: item.number,
        url:
          this.base +
          "/anime/" +
          slug +
          "?s=" +
          (item.firstSIdx + 1) +
          "&ep=" +
          (item.firstEpIdx + 1) +
          "&lang=" +
          langKey,
        title: item.title,
      });
    }
    if (episodes.length === 0) throw new Error("no episodes available in " + langKey.toUpperCase());
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const rawId = episode && episode.id ? String(episode.id) : "";
    const parts = rawId.split("|");
    const animeId = parseInt(parts[0], 10);
    const pairSpec = String(parts[1] || "");
    const langKey = parts[parts.length - 1] === "vf" ? "vf" : "vo";
    if (!(animeId > 0) || !pairSpec) {
      throw new Error("invalid episode id '" + rawId + "'");
    }

    let pairs = [];
    if (pairSpec.indexOf(":") >= 0) {
      pairs = pairSpec
        .split(",")
        .map(function (p) {
          const sp = p.split(":");
          return { sIdx: parseInt(sp[0], 10), epIdx: parseInt(sp[1], 10) };
        })
        .filter(function (p) {
          return p.sIdx >= 0 && p.epIdx >= 0;
        });
    } else {
      const sIdx = parseInt(parts[1], 10);
      const epIdx = parseInt(parts[2], 10);
      if (sIdx >= 0 && epIdx >= 0) pairs.push({ sIdx: sIdx, epIdx: epIdx });
    }
    if (pairs.length === 0) throw new Error("invalid episode coordinates in '" + rawId + "'");

    const wanted = String(server || "default").trim();
    const targetKind =
      wanted === "" || wanted.toLowerCase() === "default"
        ? null
        : this.servers.find(function (s) {
            return s.toLowerCase() === wanted.toLowerCase();
          });
    if (wanted.toLowerCase() !== "default" && wanted !== "" && !targetKind) {
      throw new Error("unknown server '" + wanted + "'");
    }

    const anime = await this._anime(animeId);
    const candidates = [];
    for (let p = 0; p < pairs.length; p++) {
      const coord = pairs[p];
      const saison = anime && Array.isArray(anime.saisons) ? anime.saisons[coord.sIdx] : null;
      const ep = saison && Array.isArray(saison.episodes) ? saison.episodes[coord.epIdx] : null;
      const lecteurs = this._lecteursOf(ep, langKey);
      for (let i = 0; i < lecteurs.length; i++) {
        const kind = this._kindOfLecteur(lecteurs[i]);
        if (!kind) continue;
        if (targetKind && kind !== targetKind) continue;
        candidates.push({ sIdx: coord.sIdx, epIdx: coord.epIdx, index: i, kind: kind, raw: lecteurs[i] });
      }
    }

    const order = this.servers;
    candidates.sort(function (a, b) {
      return order.indexOf(a.kind) - order.indexOf(b.kind);
    });

    if (candidates.length === 0) {
      throw new Error(targetKind ? "no " + targetKind + " player for this episode" : "no supported player for this episode");
    }

    const label = langKey === "vf" ? "VF" : "VOSTFR";
    const failures = [];
    for (let c = 0; c < candidates.length; c++) {
      const cand = candidates[c];
      try {
        const embedUrl = await this._resolveLecteurUrl(animeId, cand.sIdx, cand.epIdx, langKey, cand.index);
        const extracted = await this._extractEmbed(cand.kind, embedUrl);
        return {
          server: cand.kind,
          headers: { Referer: extracted.referer },
          videoSources: [
            {
              url: extracted.url,
              type: extracted.type,
              quality: "auto",
              label: label,
              subtitles: [],
            },
          ],
        };
      } catch (error) {
        failures.push(cand.kind + ": " + this._errorText(error));
      }
    }
    throw new Error(failures.join("; "));
  }

  // ---------------------------------------------------------------- Season grouping

  _buildSeasonGroups(anime, baseTitle, langKey, want2014) {
    const baseNames = this._animeNames(anime, baseTitle);
    const saisons = anime.saisons || [];
    const valid = [];
    for (let sIdx = 0; sIdx < saisons.length; sIdx++) {
      const s = saisons[sIdx];
      if (!s || !Array.isArray(s.episodes)) continue;
      if (this._countLangEpisodes(s.episodes, langKey) === 0) continue;
      valid.push({ sIdx: sIdx, title: this._text(s.title) || "Saison " + (sIdx + 1), saison: s });
    }
    if (valid.length === 0) return [];

    const bySeasonNum = {};
    const standalone = [];
    const continuousSagas = [];

    for (let i = 0; i < valid.length; i++) {
      const item = valid[i];
      const shown = item.title;
      if (this._isContinuousSaga(item.saison) || /\bSaga\s+\d+$/i.test(shown)) {
        continuousSagas.push(item.sIdx);
      }
      const exactMatch = /^Saison\s*(\d+)$/i.exec(shown);
      const dotOneMatch = /Saison(?:\s+[^0-9]+)?\s+(\d+)\.1$/i.exec(shown);
      const partTwoMatch = /Saison\s*(?:(\d+)\s*Partie\s*2|(\d+)\.5)$/i.exec(shown);

      if (exactMatch) {
        const num = parseInt(exactMatch[1], 10);
        if (!bySeasonNum[num]) bySeasonNum[num] = { num: num, primary: [], dotOne: [] };
        bySeasonNum[num].primary.push(item.sIdx);
      } else if (dotOneMatch) {
        const num = parseInt(dotOneMatch[1], 10);
        if (!bySeasonNum[num]) bySeasonNum[num] = { num: num, primary: [], dotOne: [] };
        bySeasonNum[num].dotOne.push(item.sIdx);
      } else if (partTwoMatch) {
        const num = parseInt(partTwoMatch[1] || partTwoMatch[2], 10);
        standalone.push({ sIdx: item.sIdx, seasonNum: num, partNum: 2, shown: shown });
      } else {
        standalone.push({ sIdx: item.sIdx, seasonNum: 0, partNum: 0, shown: shown });
      }
    }

    const groups = [];

    if (continuousSagas.length > 1) {
      groups.push({
        spec: continuousSagas.join(","),
        firstSeasonIdx: continuousSagas[0],
        title: baseTitle,
        altTitles: baseNames.slice(),
      });
    }

    const nums = Object.keys(bySeasonNum)
      .map(Number)
      .sort(function (a, b) {
        return a - b;
      });
    for (let i = 0; i < nums.length; i++) {
      const num = nums[i];
      const bucket = bySeasonNum[num];
      const merged = bucket.dotOne.concat(bucket.primary);
      const spec = merged.join(",");
      const firstIdx = merged[0];

      if (num === 1) {
        const s1Group = {
          spec: spec,
          firstSeasonIdx: firstIdx,
          title: baseTitle,
          altTitles: baseNames.slice(),
        };
        let s2Group = null;
        if (/\bkai\b/i.test(baseTitle) && bucket.dotOne.length > 0) {
          const sDotOne = anime.saisons[bucket.dotOne[0]];
          if (sDotOne && Array.isArray(sDotOne.episodes) && sDotOne.episodes.length > 100) {
            const s2Alts = [];
            for (let n = 0; n < baseNames.length; n++) {
              const bn = baseNames[n];
              s2Alts.push(bn + " (2014)");
              s2Alts.push(bn + ": The Final Chapters");
              s2Alts.push(bn + " Season 2");
              s2Alts.push(bn + " 2nd Season");
              s2Alts.push(bn + " II");
              s2Alts.push(bn + " 2");
            }
            s2Group = {
              spec: bucket.dotOne[0] + "@98",
              firstSeasonIdx: bucket.dotOne[0],
              title: baseTitle + " (2014)",
              altTitles: s2Alts,
            };
          }
        }
        if (want2014 && s2Group) {
          groups.push(s2Group);
          groups.push(s1Group);
        } else {
          groups.push(s1Group);
          if (s2Group) groups.push(s2Group);
        }
      } else {
        const ord = num === 2 ? "2nd" : num === 3 ? "3rd" : num + "th";
        const alts = [];
        for (let n = 0; n < baseNames.length; n++) {
          const bn = baseNames[n];
          alts.push(bn + " Season " + num);
          alts.push(bn + " Saison " + num);
          alts.push(bn + " " + ord + " Season");
          alts.push(bn + " S" + num);
        }
        groups.push({
          spec: spec,
          firstSeasonIdx: firstIdx,
          title: baseTitle + " Season " + num,
          altTitles: alts,
        });
      }
    }

    for (let i = 0; i < standalone.length; i++) {
      const st = standalone[i];
      if (st.seasonNum > 0 && st.partNum === 2) {
        const prefix = st.seasonNum > 1 ? " Season " + st.seasonNum : "";
        const alts = [];
        for (let n = 0; n < baseNames.length; n++) {
          const bn = baseNames[n];
          alts.push(bn + prefix + " Part 2");
          alts.push(bn + prefix + " Cour 2");
          alts.push(bn + " Season " + st.seasonNum + " Part 2");
          alts.push(bn + " " + st.shown);
        }
        groups.push({
          spec: String(st.sIdx),
          firstSeasonIdx: st.sIdx,
          title: baseTitle + prefix + " Part 2",
          altTitles: alts,
        });
      } else {
        const cleanShown = st.shown.replace(/\bSaison\s*(\d+)/i, "Season $1");
        const title =
          st.shown.toLowerCase().indexOf(baseTitle.toLowerCase()) === 0 ? cleanShown : baseTitle + " " + cleanShown;
        const alts = [];
        for (let n = 0; n < baseNames.length; n++) {
          alts.push(baseNames[n] + " " + st.shown);
          alts.push(baseNames[n] + " " + cleanShown);
        }
        if (groups.length === 0 && i === 0) {
          for (let n = 0; n < baseNames.length; n++) alts.push(baseNames[n]);
        }
        groups.push({
          spec: String(st.sIdx),
          firstSeasonIdx: st.sIdx,
          title: title,
          altTitles: alts,
        });
      }
    }

    return groups;
  }

  _isContinuousSaga(saison) {
    if (!saison || !Array.isArray(saison.episodes) || saison.episodes.length === 0) return false;
    const firstNum = this._epNumberFromTitle(saison.episodes[0] && saison.episodes[0].title);
    return firstNum !== null && firstNum > 1;
  }

  _epNumberFromTitle(title) {
    const m = /(?:épisode|episode)\s*(\d+)/i.exec(String(title || ""));
    return m ? parseInt(m[1], 10) : null;
  }

  _animeNames(anime, fallback) {
    const primary = [this._text(anime.title), this._text(anime.titleO)].filter(Boolean);
    const primaryBlob = primary.join(" ");
    const hasKai = /\bkai\b/i.test(primaryBlob);
    const names = [];
    const add = (val) => {
      const clean = this._text(val);
      if (!clean) return;
      if (!hasKai && (/\b(?:kai|dbk)\b/i.test(clean) || clean.indexOf("改") >= 0)) return;
      if (names.indexOf(clean) < 0) names.push(clean);
      if (/\bdragon\s*ball\s*z\s*kai\b/i.test(clean)) {
        const noZ = clean.replace(/\b(dragon\s*ball)\s*z\s*(kai)\b/i, "$1 $2");
        if (names.indexOf(noZ) < 0) names.push(noZ);
      }
    };
    add(anime.title);
    add(anime.titleO);
    if (anime.titles && typeof anime.titles === "object") {
      const keys = Object.keys(anime.titles);
      for (let k = 0; k < keys.length; k++) add(anime.titles[keys[k]]);
    }
    if (names.length === 0 && fallback) names.push(fallback);
    return names;
  }

  // ---------------------------------------------------------------- API & decoding

  async _catalogueIndex() {
    const now = Date.now();
    if (this._indexCache && now - this._indexAt < 30 * 60 * 1000) {
      return this._indexCache;
    }
    if (this._indexPromise) {
      return this._indexPromise;
    }
    const self = this;
    this._indexPromise = this._buildCatalogueIndex().then(
      function (idx) {
        self._indexPromise = null;
        return idx;
      },
      function (err) {
        self._indexPromise = null;
        throw err;
      }
    );
    return this._indexPromise;
  }

  async _buildCatalogueIndex() {
    const response = await this._fetch(this.api + "/animes", {
      Origin: this.base,
      Referer: this.base + "/",
      Accept: "application/json",
    });
    const text = await response.text();
    const index = [];
    let pos = 0;
    let count = 0;
    const marker = '"titleO":';

    while (true) {
      const tPos = text.indexOf(marker, pos);
      if (tPos < 0) break;
      pos = tPos + marker.length;

      // Yield every 400 items so QuickJS never exceeds its 4s slice limit
      count++;
      if (count % 400 === 0) {
        await new Promise(function (resolve) {
          setTimeout(resolve, 1);
        });
      }

      const pre = text.slice(Math.max(0, tPos - 600), tPos);
      const relId = pre.indexOf('"id":');
      if (relId < 0) continue;
      const idEnd = pre.indexOf(",", relId + 5);
      if (idEnd < 0) continue;
      const id = parseInt(pre.slice(relId + 5, idEnd), 10);
      if (!(id > 0)) continue;

      const slice = text.slice(pos, pos + 900);
      const m = /^("(?:[^"\\]|\\.)*"|null),"title":("(?:[^"\\]|\\.)*"|null),"titles":(\{(?:[^{}"]|"(?:[^"\\]|\\.)*")*\}|null)/.exec(
        slice
      );
      if (!m) continue;

      let titleO = null;
      let title = null;
      let titlesObj = null;
      try {
        titleO = JSON.parse(m[1]);
        title = JSON.parse(m[2]);
        titlesObj = JSON.parse(m[3]);
      } catch (e) {
        continue;
      }

      const primary = [];
      const addPrimary = (val) => {
        const clean = this._text(val);
        if (!clean) return;
        if (primary.indexOf(clean) < 0) primary.push(clean);
        if (/\bdragon\s*ball\s*z\s*kai\b/i.test(clean)) {
          const noZ = clean.replace(/\b(dragon\s*ball)\s*z\s*(kai)\b/i, "$1 $2");
          if (primary.indexOf(noZ) < 0) primary.push(noZ);
        }
      };
      addPrimary(title);
      addPrimary(titleO);
      const hasKai = /\bkai\b/i.test(primary.join(" "));

      const names = primary.slice();
      const addName = (val) => {
        const clean = this._text(val);
        if (!clean) return;
        if (!hasKai && (/\b(?:kai|dbk)\b/i.test(clean) || clean.indexOf("改") >= 0)) return;
        if (names.indexOf(clean) < 0) names.push(clean);
      };
      if (titlesObj && typeof titlesObj === "object") {
        const keys = Object.keys(titlesObj);
        for (let k = 0; k < keys.length; k++) addName(titlesObj[keys[k]]);
      }
      if (names.length > 0) {
        index.push({
          id: id,
          primary: primary,
          names: names,
          primaryWords: primary.map((p) => this._words(p)).filter((w) => w.length > 0),
          nameWords: names.map((n) => this._words(n)).filter((w) => w.length > 0),
        });
      }
    }

    if (index.length === 0) throw new Error("franime.fr catalogue is empty or unreadable");
    this._indexCache = index;
    this._indexAt = Date.now();
    return index;
  }

  async _anime(id) {
    const key = String(id);
    const cached = this._animeCache[key];
    if (cached && Date.now() - cached.at < 10 * 60 * 1000) {
      return cached.data;
    }
    if (this._animePromises[key]) {
      return this._animePromises[key];
    }
    const self = this;
    const p = (async function () {
      const response = await self._fetch(self.api + "/anime-by-id/" + encodeURIComponent(key), {
        Origin: self.base,
        Referer: self.base + "/",
        Accept: "application/json",
      });
      const text = await response.text();
      let data;
      try {
        data = JSON.parse(text);
      } catch (e) {
        throw new Error("unreadable anime data from api.franime.fr");
      }
      self._animeCache[key] = { at: Date.now(), data: data };
      return data;
    })();
    this._animePromises[key] = p;
    try {
      return await p;
    } finally {
      delete this._animePromises[key];
    }
  }

  async _resolveLecteurUrl(animeId, sIdx, epIdx, langKey, lecIdx) {
    const path = [
      this.api,
      "anime",
      encodeURIComponent(String(animeId)),
      encodeURIComponent(String(sIdx)),
      encodeURIComponent(String(epIdx)),
      encodeURIComponent(String(langKey)),
      encodeURIComponent(String(lecIdx)),
    ].join("/");
    const response = await this._fetch(path, {
      Origin: this.base,
      Referer: this.base + "/",
      Accept: "text/plain, application/json, */*",
    });
    const raw = (await response.text()).trim().replace(/^"|"$/g, "");
    if (!raw) throw new Error("empty player link from api.franime.fr");
    if (raw.indexOf("/watch2/") >= 0) {
      const decoded = this._decodeWatch2(raw);
      if (decoded) return decoded;
    }
    if (/^https?:\/\//i.test(raw)) return raw;
    throw new Error("could not decode player URL");
  }

  _decodeWatch2(watchUrl) {
    const qIndex = String(watchUrl).indexOf("?");
    if (qIndex < 0) return null;
    const query = String(watchUrl).slice(qIndex + 1);
    const pairs = query.split("&");
    for (let i = 0; i < pairs.length; i++) {
      const eq = pairs[i].indexOf("=");
      if (eq < 0) continue;
      let val = pairs[i].slice(eq + 1);
      try {
        val = decodeURIComponent(val);
      } catch (e) {}
      try {
        const hex = String(atob(val));
        if (hex.length < 16 || hex.length % 2 !== 0 || !/^[0-9a-fA-F]+$/.test(hex)) continue;
        const bytes = [];
        for (let j = 0; j < hex.length; j += 2) {
          bytes.push(parseInt(hex.slice(j, j + 2), 16));
        }
        const key = bytes[0] ^ 0x68;
        let out = "";
        for (let j = 0; j < bytes.length; j++) {
          out += String.fromCharCode(bytes[j] ^ key);
        }
        if (/^https?:\/\//i.test(out)) return out.trim();
      } catch (e) {
        continue;
      }
    }
    return null;
  }

  // ---------------------------------------------------------------- Embed extractors

  _kindOfLecteur(name) {
    const lower = String(name || "").toLowerCase();
    if (lower.indexOf("sendvid") >= 0) return "Sendvid";
    if (lower.indexOf("vidmoly") >= 0) return "Vidmoly";
    if (lower.indexOf("uqload") >= 0) return "Uqload";
    if (/smoothpre|movearnpre|dingtezuni|minochinos|vidhide/.test(lower)) return "Smoothpre";
    return null;
  }

  async _extractEmbed(kind, embedUrl) {
    const origin = this._origin(embedUrl) || this.base;
    const response = await this._fetch(embedUrl, { Referer: this.base + "/" });
    const html = await response.text();
    const finalOrigin = this._origin(response.url || embedUrl) || origin;

    if (kind === "Sendvid") {
      const mp4 = this._firstMatch(html, /https?:\/\/[^"'\s<>\\]+\.mp4[^"'\s<>\\]*/i);
      const m3u8 = this._firstMatch(html, /https?:\/\/[^"'\s<>\\]+\.m3u8[^"'\s<>\\]*/i);
      const video = mp4 || m3u8;
      if (!video) throw new Error("no video found on Sendvid");
      return { url: video, type: mp4 ? "mp4" : "m3u8", referer: finalOrigin + "/" };
    }

    if (kind === "Vidmoly") {
      const setup = /sources:\s*\[\s*\{\s*file:\s*["']([^"']+)["']/i.exec(html);
      const video = (setup && setup[1]) || this._firstMatch(html, /https?:\/\/[^"'\s<>\\]+\.m3u8[^"'\s<>\\]*/i);
      if (!video) throw new Error("no stream found on Vidmoly");
      return { url: video, type: "m3u8", referer: finalOrigin + "/" };
    }

    if (kind === "Uqload") {
      const unpacked = this._unpack(html) + "\n" + html;
      const m3u8 = this._firstMatch(unpacked, /https?:\/\/[^"'\s<>\\]+\.m3u8[^"'\s<>\\]*/i);
      const mp4 = this._firstMatch(unpacked, /https?:\/\/[^"'\s<>\\]+\.mp4[^"'\s<>\\]*/i);
      const video = m3u8 || mp4;
      if (!video) throw new Error("no stream found on Uqload");
      return { url: video, type: m3u8 ? "m3u8" : "mp4", referer: finalOrigin + "/" };
    }

    if (kind === "Smoothpre") {
      const unpacked = this._unpack(html);
      const linksMatch = /\blinks\s*=\s*(\{[^}]*\})/.exec(unpacked);
      if (linksMatch) {
        try {
          const links = JSON.parse(linksMatch[1]);
          const keys = ["hls2", "hls4", "hls3"];
          for (let i = 0; i < keys.length; i++) {
            const val = this._text(links[keys[i]]);
            if (val && /\.m3u8/i.test(val)) {
              const full = /^https?:\/\//i.test(val) ? val : finalOrigin + (val.charAt(0) === "/" ? "" : "/") + val;
              return { url: full, type: "m3u8", referer: finalOrigin + "/" };
            }
          }
        } catch (e) {}
      }
      const m3u8 = this._firstMatch(unpacked + "\n" + html, /https?:\/\/[^"'\s<>\\]+\.m3u8[^"'\s<>\\]*/i);
      if (!m3u8) throw new Error("no stream found on Smoothpre");
      return { url: m3u8, type: "m3u8", referer: finalOrigin + "/" };
    }

    throw new Error("unsupported player " + kind);
  }

  _unpack(body) {
    const re = /\}\s*\(\s*'((?:[^'\\]|\\[\s\S])*)'\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*'((?:[^'\\]|\\[\s\S])*)'\s*\.split\(\s*'\|'\s*\)/g;
    let out = "";
    let match;
    while ((match = re.exec(body || "")) !== null) {
      const payload = match[1].replace(/\\'/g, "'").replace(/\\\\/g, "\\");
      const radix = parseInt(match[2], 10);
      const words = match[4].split("|");
      const digits = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
      const decodeToken = function (token) {
        let n = 0;
        for (let i = 0; i < token.length; i++) {
          const d = digits.indexOf(token.charAt(i));
          if (d < 0 || d >= radix) return -1;
          n = n * radix + d;
        }
        return n;
      };
      out += payload.replace(/\b\w+\b/g, function (token) {
        const n = decodeToken(token);
        return n >= 0 && n < words.length && words[n] ? words[n] : token;
      });
    }
    return out;
  }

  // ---------------------------------------------------------------- helpers

  _lecteursOf(ep, langKey) {
    const langObj = ep && ep.lang && ep.lang[langKey];
    const list = langObj && Array.isArray(langObj.lecteurs) ? langObj.lecteurs : [];
    return list.filter((x) => typeof x === "string" && x.trim().length > 0);
  }

  _countLangEpisodes(episodes, langKey) {
    let count = 0;
    for (let i = 0; i < episodes.length; i++) {
      if (this._lecteursOf(episodes[i], langKey).length > 0) count++;
    }
    return count;
  }

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const raw = [opts && opts.query, media.englishTitle, media.romajiTitle].concat(media.synonyms || []);
    const queries = [];
    const add = (t) => {
      const clean = this._text(t);
      if (clean && queries.indexOf(clean) < 0) queries.push(clean);
    };
    for (let i = 0; i < raw.length; i++) add(raw[i]);
    for (let i = 0; i < raw.length; i++) add(this._withoutSeason(raw[i]));
    return queries.slice(0, 5);
  }

  _withoutSeason(title) {
    const text = this._text(title);
    if (!text) return null;
    return this._text(
      text
        .replace(/\d+\s*(?:st|nd|rd|th)\s+season/gi, "")
        .replace(/(?:season|saison|part|cour)\s*\d+/gi, "")
        .replace(/\(\s*(?:19|20)\d{2}\s*\)/g, "")
        .replace(/\bS\d+\b/g, "")
        .replace(/[:\-–]\s*$/, "")
    );
  }

  // Fast ASCII + French accent folding without calling String.prototype.normalize("NFD")
  _words(str) {
    const s = String(str || "")
      .toLowerCase()
      .replace(/[àáâãäå]/g, "a")
      .replace(/[èéêë]/g, "e")
      .replace(/[ìíîï]/g, "i")
      .replace(/[òóôõö]/g, "o")
      .replace(/[ùúûü]/g, "u")
      .replace(/[ç]/g, "c")
      .replace(/[ñ]/g, "n")
      .replace(/[\u2019']/g, "");
    return s.split(/[^a-z0-9]+/).filter(Boolean);
  }

  _scoreWords(w1, w2) {
    if (w1.length === 0 || w2.length === 0) return 0;
    let hits = 0;
    for (let i = 0; i < w1.length; i++) {
      if (w2.indexOf(w1[i]) >= 0) hits++;
    }
    if (hits === 0) return 0;
    let back = 0;
    for (let i = 0; i < w2.length; i++) {
      if (w1.indexOf(w2[i]) >= 0) back++;
    }
    return Math.min(hits / w1.length, (back / w2.length + 1) / 2);
  }

  _slug(title) {
    return this._words(title).join("-");
  }

  async _fetch(url, headers) {
    let response;
    try {
      response = await fetch(url, {
        headers: Object.assign({ "Accept-Language": "fr-FR,fr;q=0.9,en;q=0.8" }, headers || {}),
      });
    } catch (error) {
      throw new Error(this._host(url) + " unreachable (" + this._errorText(error) + ")");
    }
    if (!response.ok) {
      throw new Error("HTTP " + response.status + " from " + this._host(url));
    }
    return response;
  }

  _firstMatch(text, re) {
    const m = re.exec(String(text || ""));
    return m ? m[0] : null;
  }

  _origin(url) {
    const m = /^(https?:\/\/[^\/?#]+)/i.exec(String(url || ""));
    return m ? m[1] : "";
  }

  _host(url) {
    const m = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url || ""));
    return m ? m[1].toLowerCase() : "unknown host";
  }

  _text(val) {
    if (val === null || val === undefined) return null;
    const s = String(val).replace(/\s+/g, " ").trim();
    return s.length > 0 ? s : null;
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }
}

// FRanime (franime.me): French anime streaming, VOSTFR subtitles and VF dub, self-hosted HLS.
//
// The site is indexed by TMDB id, so an anime is matched by title through its suggest API.
// An anime page lists episodes as links "?s=<season>&e=<episode>&lang=<vostfr|vf>", and the
// playable stream of one episode comes from a small JSON endpoint:
//   GET /api/stream/tv-<tmdb>-<season>-<episode>-<lang> -> { hls, poster, duration, ... }
// `hls` is a signed, IP-bound master.m3u8 (it only opens from the IP that asked for it, which
// is the app's own connection), so the player gets it straight.

class Provider {
  constructor() {
    this.base = "https://franime.me";
    this.maxEpisodes = 2000;
  }

  getSettings() {
    return {
      episodeServers: ["FRanime"],
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    const dub = Boolean(opts && opts.dub);
    const lang = dub ? "vf" : "vostfr";
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");

    const seen = {};
    const results = [];
    for (const query of queries) {
      const items = await this._suggest(query);
      for (const item of items) {
        if (item.kind !== "tv") continue;
        if (seen[item.path]) continue;
        seen[item.path] = true;
        results.push({
          id: item.path + "|" + lang,
          title: item.name + (dub ? " VF" : " VOSTFR"),
          url: this.base + item.path,
          subOrDub: dub ? "dub" : "sub",
          year: item.year || undefined,
        });
      }
      if (results.length > 0) break;
    }
    console.log("franime: search dub=" + dub + " lang=" + lang + " -> " + results.length + " result(s)");
    return results;
  }

  async findEpisodes(id) {
    const parts = String(id).split("|");
    const path = parts[0];
    const lang = parts[1] === "vf" ? "vf" : "vostfr";
    const tmdb = this._tmdbId(path);
    if (!tmdb) throw new Error("invalid anime id '" + id + "'");

    const html = await this._get(path + "?lang=" + lang);
    const episodes = this._episodeList(html, tmdb, lang);
    console.log("franime: episodes " + path + " lang=" + lang + " -> " + episodes.length);
    if (episodes.length === 0) throw new Error(lang === "vf" ? "no VF episodes" : "no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const slug = this._text((episode && episode.id) || "");
    if (!/^tv-\d+-\d+-\d+(?:\.\d+)?-(?:vostfr|vf)$/.test(slug)) {
      throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    }
    const wanted = String(server || "FRanime").toLowerCase();
    if (wanted !== "default" && wanted !== "franime") throw new Error("unknown server '" + server + "'");

    // The other language comes along as an alternative the viewer can pick in the player.
    const lang = /-vf$/.test(slug) ? "vf" : "vostfr";
    const otherSlug = slug.replace(/-(?:vostfr|vf)$/, lang === "vf" ? "-vostfr" : "-vf");
    const [data, otherData] = await Promise.all([this._stream(slug), this._stream(otherSlug).catch(() => null)]);
    const hls = this._text(data && data.hls);
    console.log("franime: stream slug=" + slug + " -> " + (hls ? this._host(hls) : "none"));
    if (!hls || !this._isHttpUrl(hls)) throw new Error("no playable stream for this episode");

    const referer = this.base + "/";
    const versions = [{ url: hls, lang: lang, data: data }];
    const otherHls = this._text(otherData && otherData.hls);
    // One file carrying both audio tracks is offered once; the player's audio menu switches.
    if (otherHls && this._isHttpUrl(otherHls) && this._filePart(otherHls) !== this._filePart(hls)) {
      versions.push({ url: otherHls, lang: lang === "vf" ? "vostfr" : "vf", data: otherData });
    }
    const infos = await Promise.all(versions.map((v) => this._masterInfo(v.url, referer)));
    return {
      server: "FRanime",
      headers: { Referer: referer },
      videoSources: versions.map((v, i) => ({
        url: v.url,
        type: "m3u8",
        quality: this._versionLabel(v.lang, infos[i]),
        label: "FRanime",
        subtitles: this._subtitles(v.data),
      })),
    };
  }

  // "VF · 1080p", "VOSTFR · 720p", or "VF + VO · 1080p" when the file carries both audio tracks.
  _versionLabel(lang, info) {
    const audio = (info && info.audio) || [];
    const both = audio.indexOf("fr") >= 0 && audio.some((code) => code !== "fr");
    const name = both ? "VF + VO" : lang === "vf" ? "VF" : "VOSTFR";
    return name + (info && info.height ? " · " + info.height + "p" : "");
  }

  // The stream file of a signed playlist address, without its changing token.
  _filePart(url) {
    return String(url).split("?")[0];
  }

  // The tallest picture and the audio languages a master playlist offers; {} when unreadable.
  async _masterInfo(url, referer) {
    try {
      const response = await fetch(url, { headers: { Referer: referer } });
      if (!response.ok) return {};
      const text = String(await response.text());
      if (text.indexOf("#EXTM3U") < 0) return {};
      let height = 0;
      const re = /RESOLUTION=\d+x(\d+)/g;
      let m;
      while ((m = re.exec(text)) !== null) height = Math.max(height, Number(m[1]));
      const audio = [];
      const audioRe = /#EXT-X-MEDIA:[^\n]*TYPE=AUDIO[^\n]*LANGUAGE="([^"]+)"/g;
      while ((m = audioRe.exec(text)) !== null) if (audio.indexOf(m[1].toLowerCase()) < 0) audio.push(m[1].toLowerCase());
      return { height: height, audio: audio };
    } catch (error) {
      return {};
    }
  }

  // ---------------------------------------------------------------- search

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.englishTitle, media.romajiTitle].concat(media.synonyms || [])) {
      const text = this._text(title);
      if (text && queries.indexOf(text) < 0) queries.push(text);
    }
    return queries.slice(0, 3);
  }

  // /api/suggest?q=<query> -> { items: [ { kind, name, url, year } ] }
  async _suggest(query) {
    const json = await this._json("/api/suggest?q=" + encodeURIComponent(query));
    const items = json && Array.isArray(json.items) ? json.items : [];
    const out = [];
    for (const item of items) {
      if (!item) continue;
      const path = this._path(item.url);
      const name = this._text(item.name);
      if (!path || !name) continue;
      out.push({ kind: item.kind === "movie" ? "movie" : "tv", name: name, path: path, year: this._text(item.year) });
    }
    return out;
  }

  // ---------------------------------------------------------------- episodes

  // Episode links of one season/language: "?s=<s>&e=<e>&lang=<lang>". The season shown is kept
  // and numbered by its episode number; the slug is what /api/stream expects.
  _episodeList(html, tmdb, lang) {
    const $ = LoadDoc(html);
    const episodes = [];
    const seen = {};
    $("a[href]").each((i, link) => {
      const href = this._text(link.attr("href"));
      if (!href) return;
      const season = this._param(href, "s");
      const number = this._param(href, "e");
      const linkLang = this._param(href, "lang");
      if (season === null || number === null) return;
      if (linkLang && linkLang !== lang) return;
      const key = season + "/" + number;
      if (seen[key]) return;
      seen[key] = true;
      const num = Number(number);
      episodes.push({
        id: "tv-" + tmdb + "-" + season + "-" + number + "-" + lang,
        number: isFinite(num) ? num : episodes.length + 1,
        url: this.base + "/tv/" + tmdb + "?s=" + season + "&e=" + number + "&lang=" + lang,
        title: "Épisode " + number,
      });
    });
    episodes.sort((a, b) => a.number - b.number);
    return episodes.slice(0, this.maxEpisodes);
  }

  // ---------------------------------------------------------------- stream

  async _stream(slug) {
    const json = await this._json("/api/stream/" + encodeURIComponent(slug));
    if (!json || typeof json !== "object") throw new Error("the stream answer is not an object");
    return json;
  }

  // A WebVTT subtitle track travels in `thumbs.vtt`? No — that is the timeline preview. FRanime
  // burns VOSTFR subtitles into the stream, so no separate track is offered unless one appears.
  _subtitles(data) {
    const tracks = data && Array.isArray(data.subtitles) ? data.subtitles : [];
    const out = [];
    tracks.forEach((track, index) => {
      const url = this._text(track && (track.url || track.file));
      if (!url || !this._isHttpUrl(url)) return;
      out.push({
        id: (this._text(track.lang) || "sub") + "-" + index,
        url: url,
        language: this._text(track.label) || this._text(track.lang) || "Sous-titres",
        isDefault: index === 0,
        format: /\.srt(\?|$)/i.test(url) ? "srt" : /\.ass(\?|$)/i.test(url) ? "ass" : "vtt",
      });
    });
    return out;
  }

  // ---------------------------------------------------------------- http

  async _get(path) {
    const response = await this._fetch(path, "text/html");
    return response.text();
  }

  async _json(path) {
    const response = await this._fetch(path, "application/json");
    const json = response.json();
    if (json === null) throw new Error("the answer from " + path + " is not JSON");
    return json;
  }

  async _fetch(path, accept) {
    const url = this.base + path;
    let response;
    try {
      response = await fetch(url, { headers: { Referer: this.base + "/", Accept: accept, "Accept-Language": "fr-FR,fr;q=0.9" } });
    } catch (error) {
      throw new Error(this._host(this.base) + " unreachable (" + this._errorText(error) + ")");
    }
    if (!response.ok) throw new Error("HTTP " + response.status + " from " + this._host(this.base));
    return response;
  }

  // ---------------------------------------------------------------- helpers

  _path(url) {
    const text = this._text(url);
    if (!text) return null;
    const path = text.replace(/^https?:\/\/[^/]+/, "").split(/[?#]/)[0];
    return /^\/tv\/\d+-/.test(path) || /^\/movie\/\d+-/.test(path) ? path : null;
  }

  _tmdbId(path) {
    const match = /^\/tv\/(\d+)-/.exec(String(path));
    return match ? match[1] : null;
  }

  // The value of a query parameter of a URL or path, decoding HTML entities first.
  _param(href, name) {
    const clean = String(href).replace(/&amp;/g, "&");
    const match = new RegExp("[?&]" + name + "=([^&#]+)").exec(clean);
    return match ? decodeURIComponent(match[1]) : null;
  }

  _isHttpUrl(url) {
    return typeof url === "string" && /^https?:\/\/[^\s]+/i.test(url);
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _text(value) {
    if (value === null || value === undefined) return null;
    if (typeof value !== "string") value = String(value);
    const trimmed = value.replace(/\s+/g, " ").trim();
    return trimmed ? trimmed : null;
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }
}

// VoirAnime (voiranime.rip): French anime streaming, VOSTFR and VF.
//
// Search: POST /template-php/defaut/fetch.php (query=<text>) answers with <a class="va-search-result"
// href="/<slug>/"> blocks. An anime page links its seasons (/<slug>/saison-<n>/) or, for long series,
// its sagas (/<slug>/saga-<k>-<name>-episode-<a>-a-<b>/); those pages link the episodes
// (.../episode-<e>/vostfr/), and an episode page carries every reader of both languages in one
// object: const readers = {"vostfr":[...embed urls],"vf":[...]}.
// Readers used: ansembed.net (the master.m3u8 sits in the page) and smoothpre.com (packed script whose
// `links` object holds the master.m3u8). Other hosts are skipped.
//
// Only fetch and regular expressions are used, so the same file also runs under Node for testing.

class Provider {
  constructor() {
    this.base = "https://voiranime.rip";
    this.servers = ["Ansembed", "Smoothpre"];
    this.maxEpisodes = 3000;
  }

  getSettings() {
    return {
      episodeServers: this.servers.slice(),
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    const dub = Boolean(opts && opts.dub);
    const lang = dub ? "vf" : "vostfr";
    const season = this._wantedSeason(opts);
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");

    const seen = {};
    const results = [];
    for (const query of queries) {
      const items = await this._search(query);
      for (const item of items) {
        if (item.kind !== "anime" || seen[item.path]) continue;
        seen[item.path] = true;
        results.push({
          id: item.path + "|" + lang + "|" + season,
          title: season > 1 ? item.name + " Season " + season : item.name,
          url: this.base + item.path,
          subOrDub: dub ? "dub" : "sub",
        });
      }
      if (results.length > 0) break;
    }
    console.log("voiranime: search dub=" + dub + " season=" + season + " -> " + results.length + " result(s)");
    return results;
  }

  async findEpisodes(id) {
    const parts = String(id).split("|");
    const path = parts[0];
    const lang = parts[1] === "vf" ? "vf" : "vostfr";
    const wanted = Math.max(1, parseInt(parts[2], 10) || 1);
    if (!this._isAnimePath(path)) throw new Error("invalid anime id '" + id + "'");

    const animeHtml = await this._get(path);
    // [{ dir: "<section>/", number }] in episode order, each episode under its own section.
    const listed = (await this._sagaEpisodes(path, animeHtml)) || (await this._seasonEpisodes(path, animeHtml, wanted));
    if (listed.length === 0) throw new Error("no episodes listed");

    // Each page lists one language; a VF is only offered when the first episode has VF readers.
    if (lang === "vf") {
      let first = {};
      try {
        first = await this._readers(listed[0].dir + "episode-" + listed[0].number + "/vf/");
      } catch (error) {
        first = {};
      }
      if (this._readersFor(first, "vf").length === 0) throw new Error("no VF for this anime");
    }

    const episodes = listed.slice(0, this.maxEpisodes).map((e) => ({
      id: e.dir + "episode-" + e.number + "/" + lang + "/",
      number: e.shown,
      url: this.base + e.dir + "episode-" + e.number + "/" + lang + "/",
      title: "Épisode " + e.shown,
    }));
    console.log("voiranime: episodes " + path + " lang=" + lang + " -> " + episodes.length);
    return episodes;
  }

  // Long series split in sagas whose names carry their range: /<slug>/saga-1-east-blue-episode-1-a-61/
  // up to an open one (/saga-12-elbaf-episode-1156-a/). Episodes keep their absolute numbers, as the
  // catalogue lists such a series as one. Remastered cuts ("kai-saga-...") are left out. Only the open
  // saga is downloaded, to learn where it ends.
  async _sagaEpisodes(path, animeHtml) {
    const re = new RegExp('href="' + this._escape(path) + '(saga-(\\d+)-[a-z0-9-]*?episode-(\\d+)-a(?:-(\\d+))?)/"', "g");
    const sagas = {};
    let match;
    while ((match = re.exec(animeHtml)) !== null) {
      sagas[match[1]] = { dir: path + match[1] + "/", start: Number(match[3]), end: match[4] ? Number(match[4]) : null };
    }
    const list = Object.keys(sagas).map((k) => sagas[k]).sort((a, b) => a.start - b.start);
    if (list.length === 0) return null;

    const out = [];
    for (const saga of list) {
      let end = saga.end;
      if (end === null) {
        const html = await this._get(saga.dir);
        const numbers = this._numbers(html, new RegExp('href="' + this._escape(saga.dir) + 'episode-(\\d+)/(?:vostfr|vf)/"', "g"));
        end = numbers.length > 0 ? numbers[numbers.length - 1] : saga.start - 1;
      }
      for (let n = saga.start; n <= end && out.length < this.maxEpisodes; n += 1) {
        out.push({ dir: saga.dir, number: n, shown: n });
      }
    }
    return out;
  }

  // Seasons: /<slug>/saison-<n>/ pages listing /episode-<e>/<lang>/. The wanted season is used when the
  // site has it, else the first. A season numbered on from the previous one (25, 26, ...) is shown
  // from 1, as catalogues list each season on its own.
  async _seasonEpisodes(path, animeHtml, wanted) {
    const seasons = this._numbers(animeHtml, new RegExp('href="' + this._escape(path) + 'saison-(\\d+)/"', "g"));
    if (seasons.length === 0) return [];
    const season = seasons.indexOf(wanted) >= 0 ? wanted : seasons[0];
    const dir = path + "saison-" + season + "/";
    const html = await this._get(dir);
    const numbers = this._numbers(html, new RegExp('href="' + this._escape(dir) + 'episode-(\\d+(?:\\.\\d+)?)/(?:vostfr|vf)/"', "g"));
    const offset = numbers.length > 0 && numbers[0] > 1 ? numbers[0] - 1 : 0;
    return numbers.map((n) => ({ dir: dir, number: n, shown: n - offset }));
  }

  async findEpisodeServer(episode, server) {
    const path = this._text((episode && episode.id) || "");
    const m = /^\/[a-z0-9-]+\/[a-z0-9-]+\/episode-\d+(?:\.\d+)?\/(vostfr|vf)\/$/.exec(path || "");
    if (!m) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const lang = m[1];

    const other = lang === "vf" ? "vostfr" : "vf";
    const name = this._serverName(server);

    const readers = await this._readers(path);
    if (this._readersFor(readers, lang).length === 0) throw new Error("no " + lang.toUpperCase() + " reader for this episode");

    // Every version this host has (vf, vf2, ... then the other language), one stream each: the
    // viewer picks one in the player. A dead link is common, so each link of a version is tried.
    const keys = this._versionKeys(readers, lang).concat(this._versionKeys(readers, other));
    const problems = [];
    const found = await Promise.all(
      keys.map(async (key) => {
        for (const url of (readers[key] || []).filter((u) => this._host(u).indexOf(name.toLowerCase()) >= 0)) {
          try {
            const stream = await this._extract(name, url, path);
            const info = await this._masterInfo(stream.url, stream.origin + "/");
            return { key: key, url: stream.url, origin: stream.origin, height: info.height || 0 };
          } catch (error) {
            problems.push(key + ": " + this._errorText(error));
          }
        }
        return null;
      })
    );
    const streams = found.filter((s) => s !== null);
    // The asked language must be there; the other one only comes along as an alternative.
    if (!streams.some((s) => this._isVersionOf(s.key, lang))) {
      throw new Error(problems.length > 0 ? problems.join("; ") : "no " + name + " reader for this episode in " + lang.toUpperCase());
    }
    // The asked language first, best picture first within each language.
    const rank = (s) => (this._isVersionOf(s.key, lang) ? 0 : 1);
    streams.sort((a, b) => rank(a) - rank(b) || b.height - a.height);
    console.log("voiranime: " + path + " -> " + name + " " + streams.map((s) => s.key + ":" + (s.height || "?")).join(", "));
    return {
      server: name,
      headers: { Referer: streams[0].origin + "/" },
      videoSources: streams.map((s) => ({
        url: s.url,
        type: "m3u8",
        quality: this._versionName(s.key) + (s.height ? " · " + s.height + "p" : ""),
        label: name,
        subtitles: [],
      })),
    };
  }

  // The server asked for, as named in getSettings(); "default" is the first.
  _serverName(server) {
    const wanted = String(server || "").toLowerCase();
    return this.servers.find((s) => s.toLowerCase() === wanted) || this.servers[0];
  }

  // The keys of a language and of its other versions ("vf", "vf2", ...), in that order.
  _versionKeys(readers, lang) {
    return Object.keys(readers || {})
      .filter((key) => this._isVersionOf(key, lang))
      .sort((a, b) => (parseInt(a.slice(lang.length), 10) || 1) - (parseInt(b.slice(lang.length), 10) || 1));
  }

  _isVersionOf(key, lang) {
    return key === lang || (key.indexOf(lang) === 0 && /^\d+$/.test(key.slice(lang.length)));
  }

  // "vf" -> "VF", "vf2" -> "VF 2", "vostfr" -> "VOSTFR".
  _versionName(key) {
    const m = /^([a-z]+?)(\d*)$/.exec(key);
    return m ? m[1].toUpperCase() + (m[2] ? " " + m[2] : "") : key.toUpperCase();
  }

  // Every reader link of a language and of its other versions, in that order.
  _readersFor(readers, lang) {
    const out = [];
    for (const key of this._versionKeys(readers, lang)) {
      for (const url of readers[key] || []) if (out.indexOf(url) < 0) out.push(url);
    }
    return out;
  }

  // The tallest picture a master playlist offers, read to label the version; {} when unreadable.
  async _masterInfo(url, referer) {
    try {
      const response = await fetch(url, { headers: { Referer: referer } });
      if (!response.ok) return {};
      const text = String(await response.text());
      if (text.indexOf("#EXTM3U") < 0) return {};
      let height = 0;
      const re = /RESOLUTION=\d+x(\d+)/g;
      let m;
      while ((m = re.exec(text)) !== null) height = Math.max(height, Number(m[1]));
      return { height: height };
    } catch (error) {
      return {};
    }
  }

  // ---------------------------------------------------------------- search

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const titles = [opts && opts.query, media.englishTitle, media.romajiTitle].concat(media.synonyms || []);
    const queries = [];
    const add = (title) => {
      const text = this._text(title);
      if (text && queries.indexOf(text) < 0) queries.push(text);
    };
    titles.forEach(add);
    titles.forEach((title) => add(this._withoutSeason(title)));
    return queries.slice(0, 4);
  }

  // The season a catalogue title points at ("2nd Season", "Season 2", "Saison 2", "S2"), else 1.
  _wantedSeason(opts) {
    const media = (opts && opts.media) || {};
    const titles = [opts && opts.query, media.englishTitle, media.romajiTitle].concat(media.synonyms || []);
    const patterns = [/(\d+)\s*(?:st|nd|rd|th)\s+season/i, /season\s*(\d+)/i, /saison\s*(\d+)/i, /\bS(\d+)\b/];
    for (const title of titles) {
      const text = this._text(title);
      if (!text) continue;
      for (const re of patterns) {
        const found = re.exec(text);
        if (found && Number(found[1]) > 0) return Number(found[1]);
      }
    }
    return 1;
  }

  _withoutSeason(title) {
    const text = this._text(title);
    if (!text) return null;
    return this._text(
      text
        .replace(/\d+\s*(?:st|nd|rd|th)\s+season/gi, "")
        .replace(/(?:season|saison|part|cour)\s*\d+/gi, "")
        .replace(/\bS\d+\b/g, "")
        .replace(/[:\-–]\s*$/, "")
    );
  }

  // <a href="/<slug>/" class="va-search-result"> ... <span class="va-search-result-title">Name</span>
  // <span class="va-search-result-subtitle">Anime|Film|...</span></a>
  async _search(query) {
    const html = await this._post("/template-php/defaut/fetch.php", "query=" + encodeURIComponent(query));
    const items = [];
    const blockRe = /<a[^>]*href="(\/[^"]+\/)"[^>]*class="va-search-result"[^>]*>([\s\S]*?)<\/a>/g;
    let block;
    while ((block = blockRe.exec(html)) !== null) {
      const name = this._decode((/class="va-search-result-title">([\s\S]*?)<\/span>/.exec(block[2]) || [])[1]);
      const kind = this._decode((/class="va-search-result-subtitle">([\s\S]*?)<\/span>/.exec(block[2]) || [])[1]);
      if (!name || !this._isAnimePath(block[1])) continue;
      items.push({ path: block[1], name: name, kind: /anime/i.test(kind || "") ? "anime" : "other" });
    }
    return items;
  }

  // ---------------------------------------------------------------- readers

  // Kept a few minutes: the app asks every server of an episode at once, all from the same page.
  async _readers(path) {
    const store = typeof $store !== "undefined" ? $store : null;
    const cached = store ? store.get("voiranime/readers" + path) : null;
    if (cached && Date.now() - cached.at < 5 * 60 * 1000) return cached.readers;
    const readers = await this._readersFromPage(path);
    if (store) store.set("voiranime/readers" + path, { at: Date.now(), readers: readers });
    return readers;
  }

  async _readersFromPage(path) {
    const html = await this._get(path);
    const found = /const\s+readers\s*=\s*(\{[\s\S]*?\});/.exec(html);
    if (!found) throw new Error("no reader list on the episode page");
    let readers;
    try {
      readers = JSON.parse(found[1]);
    } catch (error) {
      throw new Error("the reader list could not be read");
    }
    const out = {};
    for (const lang of Object.keys(readers || {})) {
      out[lang] = (Array.isArray(readers[lang]) ? readers[lang] : []).filter((u) => this._isHttpUrl(u));
    }
    return out;
  }

  async _extract(name, url, episodePath) {
    const origin = this._origin(url);
    const response = await this._fetch(url, { Referer: this.base + episodePath });
    const html = await response.text();
    const finalOrigin = this._origin(response.url || url) || origin;

    if (name === "Smoothpre") {
      const unpacked = this._unpack(html) || "";
      const links = /links\s*=\s*(\{[^}]*\})/.exec(unpacked);
      if (links) {
        try {
          const all = JSON.parse(links[1]);
          for (const key of ["hls2", "hls4", "hls3"]) {
            const link = this._text(all[key]);
            if (link) return { url: link.charAt(0) === "/" ? finalOrigin + link : link, origin: finalOrigin };
          }
        } catch (error) {
          // falls through to the plain search below
        }
      }
      const inside = this._m3u8(unpacked);
      if (inside) return { url: inside, origin: finalOrigin };
    }

    const plain = this._m3u8(html) || this._m3u8(this._unpack(html) || "");
    if (!plain) throw new Error("no stream in the player page");
    return { url: plain, origin: finalOrigin };
  }

  // Dean Edwards packer: eval(function(p,a,c,k,e,d){...}('payload',a,c,'w|o|r|d|s'.split('|'),0,{}))
  _unpack(source) {
    const m = /eval\(function\(p,a,c,k,e,[dr]\)\{[\s\S]*?\}\(\s*'([\s\S]*?)',\s*(\d+),\s*(\d+),\s*'([\s\S]*?)'\.split\('\|'\)/.exec(source || "");
    if (!m) return null;
    let payload = m[1].replace(/\\'/g, "'");
    const radix = parseInt(m[2], 10);
    const count = parseInt(m[3], 10);
    const words = m[4].split("|");
    const digits = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    const encode = (n) => (n < radix ? "" : encode(Math.floor(n / radix))) + digits[n % radix];
    for (let i = count - 1; i >= 0; i--) {
      if (words[i]) payload = payload.replace(new RegExp("\\b" + encode(i) + "\\b", "g"), words[i]);
    }
    return payload;
  }

  _m3u8(text) {
    const found = /https?:\/\/[^"'\s\\]+\.m3u8[^"'\s\\]*/.exec(text || "");
    return found ? found[0] : null;
  }

  // ---------------------------------------------------------------- http

  async _get(path) {
    const response = await this._fetch(this.base + path, { Referer: this.base + "/" });
    return response.text();
  }

  async _post(path, body) {
    const response = await this._fetch(this.base + path, {
      Referer: this.base + "/",
      "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8",
      "X-Requested-With": "XMLHttpRequest",
    }, body);
    return response.text();
  }

  async _fetch(url, headers, body) {
    const init = { headers: Object.assign({ "Accept-Language": "fr-FR,fr;q=0.9" }, headers || {}) };
    if (body !== undefined) {
      init.method = "POST";
      init.body = body;
    }
    let response;
    try {
      response = await fetch(url, init);
    } catch (error) {
      throw new Error(this._host(url) + " unreachable (" + this._errorText(error) + ")");
    }
    if (!response.ok) throw new Error("HTTP " + response.status + " from " + this._host(url));
    return response;
  }

  // ---------------------------------------------------------------- helpers

  _numbers(html, re) {
    const seen = {};
    let match;
    while ((match = re.exec(html || "")) !== null) seen[match[1]] = true;
    return Object.keys(seen).map(Number).filter((n) => isFinite(n) && n > 0).sort((a, b) => a - b);
  }

  _isAnimePath(path) {
    return typeof path === "string" && /^\/[a-z0-9-]+\/$/.test(path);
  }

  _escape(text) {
    return String(text).replace(/[.*+?^${}()|[\]\\\/]/g, "\\$&");
  }

  _decode(text) {
    if (typeof text !== "string") return null;
    return this._text(
      text
        .replace(/<[^>]+>/g, " ")
        .replace(/&amp;/g, "&")
        .replace(/&quot;/g, '"')
        .replace(/&#0?39;|&apos;/g, "'")
        .replace(/&lt;/g, "<")
        .replace(/&gt;/g, ">")
    );
  }

  _isHttpUrl(url) {
    return typeof url === "string" && /^https?:\/\/[^\s]+$/i.test(url);
  }

  _origin(url) {
    const match = /^(https?:\/\/[^\/?#]+)/i.exec(String(url || ""));
    return match ? match[1].toLowerCase() : null;
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _text(value) {
    if (value === null || value === undefined) return null;
    if (typeof value !== "string") value = String(value);
    const trimmed = value.replace(/\s+/g, " ").trim();
    return trimmed ? trimmed : null;
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }
}
